rep("function tout(){ if (S.atelier) {", r"""function blocDe(el){ const li = el.closest('[data-p]'); if (!li) return null; const [bi, ei] = li.dataset.p.split('.'); return { bi: +bi, ei: ei === 't' ? 't' : +ei, li }; }
function marquerModif(quoi){ S.atelierDirty = Date.now(); const sv = $('at-save'); if (sv) { sv.className = 'at-save dirty'; sv.textContent = '● modification en cours — enregistrement dans 3 s'; } journal('atelier-modif', quoi); }
function ecrireDansDiapo(el){ const b = blocDe(el); if (!b) return; const e = ecran(); const bloc = e.blocs[b.bi]; if (!bloc) return; const txt = el.textContent; if (b.ei === 't') bloc.txt = txt; else { bloc.el = bloc.el || []; bloc.el[b.ei] = txt; } marquerModif({ di: S.di, bi: b.bi, ei: b.ei, n: txt.length }); }
function elementsEditables(){ return Array.from(document.querySelectorAll('#mur [data-p][contenteditable]')); }
function elementsDeLaDiapo(){ return Array.from(document.querySelectorAll('#mur [data-p]')); }
function focaliser(el, fin){ if (!el) return; if (!el.getAttribute('contenteditable')) brancherAtelier(); /* le rendu du mur est différé : on branche avant de mettre le curseur */ el.focus(); if (fin !== false) { const r = document.createRange(); r.selectNodeContents(el); r.collapse(false); const sel = getSelection(); sel.removeAllRanges(); sel.addRange(r); } }
const atBranches = new WeakSet(); /* les nœuds branchés (un clone du morph n'y est pas : il sera rebranché) */
let atObs = null; function observerMur(){ if (atObs) return; const mur = $('mur'); if (!mur) return; atObs = new MutationObserver(() => { if (S.atelier) brancherAtelier(); }); atObs.observe(mur, { childList: true, subtree: true }); }
function brancherAtelier(){ const mur = $('mur'); if (!mur || !S.atelier) return; const e = ecran(); if (!e || e.role === 'fin') return;
  elementsDeLaDiapo().forEach(x => { if (!x.getAttribute('contenteditable')) { x.setAttribute('contenteditable', 'plaintext-only'); x.setAttribute('spellcheck', 'false'); x.title = 'Écris ici : c\'est enregistré tout seul quelques secondes après (Tab : l\'élément suivant · Entrée : un nouvel élément · Échap : annule une ligne vide)'; } /* le morph réutilise les nœuds et retire les attributs absents du nouveau rendu : on les repose à chaque passage ; les écouteurs, eux, une seule fois */ if (atBranches.has(x)) return; atBranches.add(x);
    x.addEventListener('focus', () => { mur.querySelectorAll('.bloc-edit').forEach(z => z.classList.remove('bloc-edit')); const conteneur = x.closest('ul, ol, .bloc, p') || x.parentElement; conteneur.classList.add('bloc-edit'); poserBarreBloc(conteneur, blocDe(x)); });
    x.addEventListener('input', () => ecrireDansDiapo(x));
    x.addEventListener('keydown', ev => { const e = ecran(); /* la diapo du moment, pas celle du branchement : le morph réutilise les nœuds d'une diapo à l'autre */ const all = elementsEditables(); const k = all.indexOf(x); if (['Tab', 'Enter', 'Escape'].includes(ev.key) || (ev.altKey && /^Arrow/.test(ev.key))) ev.stopPropagation(); /* le clavier global (Échap ferme, flèches naviguent) ne reçoit pas ce que l'atelier traite */ if (ev.key === 'Tab') { ev.preventDefault(); const n = all[k + (ev.shiftKey ? -1 : 1)]; if (n) focaliser(n); return; } if (ev.key === 'Enter') { ev.preventDefault(); const b = blocDe(x); if (!b || b.ei === 't') { const n = all[k + 1]; if (n) focaliser(n); return; } const bloc = e.blocs[b.bi]; bloc.el = bloc.el || []; bloc.el.splice(b.ei + 1, 0, ''); marquerModif({ di: S.di, bi: b.bi, ajout: b.ei + 1 }); tout(); setTimeout(() => { const nv = mur.querySelector(`[data-p="${b.bi}.${b.ei + 1}"]`); if (nv) { nv.setAttribute('data-vide', '1'); focaliser(nv); } }, 0); return; } if (ev.key === 'Escape') { const b = blocDe(x); if (b && b.ei !== 't' && !x.textContent.trim()) { ev.preventDefault(); const bloc = e.blocs[b.bi]; if ((bloc.el || []).length > 1) { bloc.el.splice(b.ei, 1); marquerModif({ di: S.di, bi: b.bi, retrait: b.ei }); tout(); setTimeout(() => { const prev = mur.querySelector(`[data-p="${b.bi}.${Math.max(0, b.ei - 1)}"]`); if (prev) focaliser(prev); }, 0); } } return; } if (ev.altKey && (ev.key === 'ArrowUp' || ev.key === 'ArrowDown')) { ev.preventDefault(); const b = blocDe(x); if (b) deplacerBloc(b.bi, ev.key === 'ArrowUp' ? -1 : 1); } });
  }); }
function poserBarreBloc(conteneur, b){ const mur = $('mur'); mur.querySelectorAll('.bloc-barre').forEach(z => z.remove()); if (!b) return; const e = ecran(); const bloc = e.blocs[b.bi]; if (!bloc) return; const n = (bloc.el || []).length; const barre = document.createElement('div'); barre.className = 'bloc-barre'; barre.innerHTML = `<span class="nom">BLOC ${b.bi + 1} · ${esc((bloc.t || '').toUpperCase())} · ${n} ÉLÉMENT${n > 1 ? 'S' : ''}</span><button data-bb="haut" title="Monte ce bloc d\'un cran dans la diapo (Alt + ↑)" ${b.bi === 0 ? 'disabled' : ''}>▲</button><button data-bb="bas" title="Descend ce bloc d\'un cran (Alt + ↓)" ${b.bi >= e.blocs.length - 1 ? 'disabled' : ''}>▼</button><span class="sep"></span><button data-bb="etape" title="Ajoute un élément à la fin de ce bloc (Entrée en fin de ligne fait pareil)">+ étape</button><button data-bb="suppr" title="Supprime ce bloc — le site demande confirmation si des réponses d\'élèves y sont accrochées (1.8)">✕</button>`; conteneur.appendChild(barre); barre.querySelectorAll('[data-bb]').forEach(bt => bt.addEventListener('mousedown', ev => ev.preventDefault())); barre.querySelector('[data-bb="haut"]').onclick = () => deplacerBloc(b.bi, -1); barre.querySelector('[data-bb="bas"]').onclick = () => deplacerBloc(b.bi, 1); barre.querySelector('[data-bb="etape"]').onclick = () => { bloc.el = bloc.el || []; bloc.el.push(''); marquerModif({ di: S.di, bi: b.bi, ajout: bloc.el.length - 1 }); tout(); setTimeout(() => { const nv = mur.querySelector(`[data-p="${b.bi}.${bloc.el.length - 1}"]`); if (nv) { nv.setAttribute('data-vide', '1'); focaliser(nv); } }, 0); }; barre.querySelector('[data-bb="suppr"]').onclick = () => supprimerBloc(b.bi); }
function deplacerBloc(bi, sens){ const e = ecran(); const j = bi + sens; if (j < 0 || j >= e.blocs.length) return; const t = e.blocs[bi]; e.blocs[bi] = e.blocs[j]; e.blocs[j] = t; marquerModif({ di: S.di, bloc: bi, vers: j }); tout(); setTimeout(() => { const el = $('mur').querySelector(`[data-p^="${j}."]`); if (el) focaliser(el, false); }, 0); }
function supprimerBloc(bi){ const e = ecran(); const st = parDiapo[K(S.di)] || { reps: {} }; const reps = Object.keys(st.reps || {}).filter(k => +k === bi && (st.reps[k] || []).length).length; if (reps && !confirm('Des réponses d\'élèves sont accrochées à ce bloc : les supprimer avec lui ?')) return; if (e.blocs.length <= 1) { alert('Une diapo garde au moins un bloc.'); return; } e.blocs.splice(bi, 1); marquerModif({ di: S.di, supprime: bi, reps }); tout(); }
setInterval(() => { const sv = $('at-save'); if (!sv || !S.atelier) return; if (S.atelierDirty) { const d = Math.ceil((3000 - (Date.now() - S.atelierDirty)) / 1000); if (d <= 0) { S.atelierDirty = null; S.atelierSaved = Date.now(); sv.className = 'at-save'; sv.textContent = '✔ enregistré'; journal('atelier-enregistre', { di: S.di }); } else sv.textContent = '● modification en cours — enregistrement dans ' + d + ' s'; } else if (S.atelierSaved) { const n = Math.round((Date.now() - S.atelierSaved) / 1000); sv.textContent = '✔ enregistré' + (n >= 1 ? ' il y a ' + (n < 60 ? n + ' s' : Math.round(n / 60) + ' min') : ''); } }, 1000);
function tout(){ if (S.atelier) { observerMur(); setTimeout(brancherAtelier, 0); """)
