rep("function tout(){ if (S.atelier) { observerMur(); setTimeout(brancherAtelier, 0);", r"""function tout(){ if (S.atelier) { observerMur(); setTimeout(brancherAtelier, 0); const ab = $('at-bloc'); if (ab && !ab._ok) { ab._ok = true; ab.onclick = () => { const e = ecran(); if (!e || e.role === 'fin') return; e.blocs.push({ t: 'consigne', bid: 'b' + Date.now().toString(36), txt: 'Nouveau bloc', el: [''] }); marquerModif({ di: S.di, bloc: 'ajout', bi: e.blocs.length - 1 }); tout(); setTimeout(() => { const nv = $('mur').querySelector('[data-p="' + (e.blocs.length - 1) + '.t"]'); if (nv) focaliser(nv); }, 0); }; } const ae = $('at-etape'); if (ae && !ae._ok) { ae._ok = true; ae.onclick = () => { const e = ecran(); if (!e || e.role === 'fin') return; const b = document.activeElement && blocDe(document.activeElement); const bi = b ? b.bi : e.blocs.length - 1; const bloc = e.blocs[bi]; if (!bloc) return; bloc.el = bloc.el || []; bloc.el.push(''); marquerModif({ di: S.di, bi, ajout: bloc.el.length - 1 }); tout(); setTimeout(() => { const nv = $('mur').querySelector('[data-p="' + bi + '.' + (bloc.el.length - 1) + '"]'); if (nv) { nv.setAttribute('data-vide', '1'); focaliser(nv); } }, 0); }; }""")
rep("function droiteAtelier(){ const E = seance().ecrans; const e = ecran();","function droiteAtelier(){ const E = seance().ecrans; const e = ecran(); const aide = S.aideFermee ? '' : '<div class=\"at-d at-aide\" id=\"at-aide\"><span class=\"x\" title=\"Ferme l\\'aide\">✕</span><b>Écrire dans la diapo</b> — un clic dans un bloc, tu tapes ; <b>Tab</b> passe à l\\'élément suivant, <b>Maj + Tab</b> au précédent, <b>Entrée</b> en fin de ligne crée l\\'élément suivant, <b>Échap</b> annule une ligne vide ; <b>Alt + ↑ / ↓</b> monte ou descend le bloc. Rien à sauver : c\\'est enregistré quelques secondes après la frappe, et le témoin le dit.</div>'; return aide + droiteAtelier0(e, E); }\nfunction droiteAtelier0(e, E){")
